const fs = require('fs');

function main(input) {
  const tokens = input.trim().split(/\s+/);
  let ptr = 0;
  const N = parseInt(tokens[ptr++], 10);
  const X1 = BigInt(tokens[ptr++]);
  const X2 = BigInt(tokens[ptr++]);

  const K = 2147483648n;    // 2^31 > 2e9, garante ordenacao lexicografica
  const HALF = 1000000000n;

  // Ideia: duas retas com inclinacoes A_i < A_j cruzam dentro de [X1, X2]
  // ssex  y_i(X1) >= y_j(X1)  e  y_i(X2) <= y_j(X2).
  // Isso equivale acontar pares cuja ordem relativa em "(h asc, A desc)"
  // e oposta a ordem em "(g asc, A asc)", com h = A*X1+B, g = A*X2+B.
  // (pares com A igual tem h e g na mesma ordem => nunca contam)

  const keyL = new Array(N);
  const keyR = new Array(N);

  for (let i = 0; i < N; i++) {
    const A = BigInt(tokens[ptr++]);
    const B = BigInt(tokens[ptr++]);
    const h = A * X1 + B;
    const g = A * X2 + B;
    keyL[i] = h * K + (HALF - A);
    keyR[i] = g * K + (A + HALF);
  }

  const idx = new Array(N);
  for (let i = 0; i < N; i++) idx[i] = i;

  const orderL = idx.slice().sort((a, b) =>
    keyL[a] < keyL[b] ? -1 : keyL[a] > keyL[b] ? 1 : a - b);
  const orderR = idx.slice().sort((a, b) =>
    keyR[a] < keyR[b] ? -1 : keyR[a] > keyR[b] ? 1 : a - b);

  const pos = new Int32Array(N);
  for (let k = 0; k < N; k++) pos[orderL[k]] = k;

  // numero de inversoes entre as duas permutacoes, via BIT
  const bit = new Int32Array(N + 1);
  let total = 0;
  for (let k = 0; k < N; k++) {
    const r = pos[orderR[k]] + 1;
    let s = 0;
    for (let i = r; i > 0; i -= i & -i) s += bit[i];
    total += k - s;
    for (let i = r; i <= N; i += i & -i) bit[i]++;
  }

  process.stdout.write(total.toString() + "\n");
}

let input = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", c => input += c);
process.stdin.on("end", () => main(input));
